function solve(values, k) {
  const dummy = { val: 0, next: null };
  let tail = dummy;
  for (const v of values) { tail.next = { val: v, next: null }; tail = tail.next; }
  let prevTail = dummy;
  let cur = dummy.next;
  while (cur) {
    let probe = cur;
    for (let i = 0; i < k; i++) {
      if (!probe) return toArray(dummy.next);
      probe = probe.next;
    }
    let prev = null;
    let node = cur;
    for (let i = 0; i < k; i++) {
      const next = node.next;
      node.next = prev;
      prev = node;
      node = next;
    }
    prevTail.next = prev;
    cur.next = node;
    prevTail = cur;
    cur = node;
  }
  return toArray(dummy.next);
}
function toArray(head) {
  const out = [];
  for (let p = head; p; p = p.next) out.push(p.val);
  return out;
}
